fn installed_path(name: &str, fallback: &str) -> Result<std::path::PathBuf> {
    let path = std::env::var_os(name)
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(fallback));
    ensure!(path.is_absolute(), "{name} must be an absolute path");
    Ok(path)
}
